{
  "root_cause": "The datepicker's keydown handler (_onKeyChange) lacks a case for the Tab key (keyCode 9). When the picker is visible, the handler does not consume the key, but the blur event triggered by the focus change schedules a hide that, due to a race condition, refocuses the field before the blur completes, causing focus to remain on the check-in field. Additionally, the blur handler (_onInputBlur) unconditionally hides the picker when the field loses focus, even when the user is tabbing to the next field, which can cause a refocus via the picker's draw cycle.",
  "repair_strategy": "Add a case for keyCode 9 in _onKeyChange that sets a flag indicating Tab was pressed. In _onInputBlur, check this flag and skip hiding the picker when Tab was the cause of the blur. Clear the flag after a short timeout to avoid interfering with other blur events.",
  "edits": [
    {
      "path": "pikaday.js",
      "sha256": "a50b66482ec18884a7200882e9b523d9192b224b40b296cdd4080530f114fa75",
      "before": "    Pikaday = function(options)
    {
        var self = this,
            opts = self.config(options);

        self._onMouseDown = function(e)",
      "after": "    Pikaday = function(options)
    {
        var self = this,
            opts = self.config(options),
            tabPressed = false;

        self._onMouseDown = function(e)"
    },
    {
      "path": "pikaday.js",
      "sha256": "a50b66482ec18884a7200882e9b523d9192b224b40b296cdd4080530f114fa75",
      "before": "        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible()) {

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                    case 8:
                    case 46:
                        self.setDate(null);
                        break;
                }
            }
        };",
      "after": "        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible()) {

                switch(e.keyCode){
                    case 9:
                        tabPressed = true;
                        sto(function() { tabPressed = false; }, 0);
                        break;
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                    case 8:
                    case 46:
                        self.setDate(null);
                        break;
                }
            }
        };"
    },
    {
      "path": "pikaday.js",
      "sha256": "a50b66482ec18884a7200882e9b523d9192b224b40b296cdd4080530f114fa75",
      "before": "        self._onInputBlur = function()
        {
            // IE allows pika div to gain focus; catch blur the field
            var pEl = document.activeElement;
            do {
                if (hasClass(pEl, 'pika-single')) {
                    return;
                }
            } while ((pEl = pEl.parentNode));

            if (!self._c) {
                self._b = sto(function() {
                    self.hide();
                }, 50);
            }
            self._c = false;
        };",
      "after": "        self._onInputBlur = function()
        {
            // IE allows pika div to gain focus; catch blur the field
            var pEl = document.activeElement;
            do {
                if (hasClass(pEl, 'pika-single')) {
                    return;
                }
            } while ((pEl = pEl.parentNode));

            if (tabPressed) {
                tabPressed = false;
                return;
            }

            if (!self._c) {
                self._b = sto(function() {
                    self.hide();
                }, 50);
            }
            self._c = false;
        };"
    }
